def check(ctx):
    occupancy = ctx['SubjectProperty.occupancy_subtype']
    missing = rules_lib.gaps(occupancy=occupancy)
    if missing:
        return rules_lib.unknown(*missing)

    is_investment = (
        rules_lib.same(occupancy, 'investment')
        or rules_lib.same(occupancy, 'investment property')
    )

    tenant_ok = True
    if is_investment:
        has_current_lease = ctx['SubjectProperty.has_current_lease']
        is_vacant = ctx['SubjectProperty.is_vacant']
        missing = rules_lib.gaps(
            has_current_lease=has_current_lease,
            is_vacant=is_vacant,
        )
        if missing:
            return rules_lib.unknown(*missing)

        has_current_lease = rules_lib.flag(has_current_lease)
        is_vacant = rules_lib.flag(is_vacant)
        if has_current_lease is None:
            return rules_lib.unknown('has_current_lease')
        if is_vacant is None:
            return rules_lib.unknown('is_vacant')
        tenant_ok = has_current_lease and not is_vacant

    reserves_months = ctx['RatioSet.reserves_months']
    is_interest_only = ctx['MortgageLoanInformation.is_interest_only']
    is_escrow_waived = ctx['LoanCore.is_escrow_waived']
    missing = rules_lib.gaps(
        reserves_months=reserves_months,
        is_interest_only=is_interest_only,
        is_escrow_waived=is_escrow_waived,
    )
    if missing:
        return rules_lib.unknown(*missing)

    is_interest_only = rules_lib.flag(is_interest_only)
    is_escrow_waived = rules_lib.flag(is_escrow_waived)
    if is_interest_only is None:
        return rules_lib.unknown('is_interest_only')
    if is_escrow_waived is None:
        return rules_lib.unknown('is_escrow_waived')

    return (
        tenant_ok
        and reserves_months >= 24
        and not is_interest_only
        and not is_escrow_waived
    )

