def check(ctx):
    property_type = ctx['SubjectProperty.property_type']
    missing = rules_lib.gaps(property_type=property_type)
    if missing:
        return rules_lib.unknown(*missing)

    if rules_lib.same(property_type, 'Non-Warrantable Condo'):
        loan_purpose = ctx['LoanCore.loan_purpose']
        state = ctx['SubjectProperty.state']
        cltv = ctx['LoanCore.cltv_percent']
        missing = rules_lib.gaps(loan_purpose=loan_purpose, state=state, cltv=cltv)
        if missing:
            return rules_lib.unknown(*missing)
        if rules_lib.same(loan_purpose, 'Purchase'):
            cap = 80
        elif rules_lib.same(loan_purpose, 'Refi R/T'):
            cap = 75
        elif rules_lib.same(loan_purpose, 'Refi C/O'):
            cap = 75
        else:
            return rules_lib.unknown('LoanCore.loan_purpose')
        if rules_lib.same(state, 'Florida', 'FL'):
            cap -= 5
        return cltv <= cap

    if rules_lib.same(property_type, 'Condotel / PUDtel'):
        loan_purpose = ctx['LoanCore.loan_purpose']
        state = ctx['SubjectProperty.state']
        cltv = ctx['LoanCore.cltv_percent']
        missing = rules_lib.gaps(loan_purpose=loan_purpose, state=state, cltv=cltv)
        if missing:
            return rules_lib.unknown(*missing)
        if rules_lib.same(loan_purpose, 'Purchase'):
            cap = 75
        elif rules_lib.same(loan_purpose, 'Refi R/T'):
            cap = 70
        elif rules_lib.same(loan_purpose, 'Refi C/O'):
            cap = 65
        else:
            return rules_lib.unknown('LoanCore.loan_purpose')
        if rules_lib.same(state, 'Florida', 'FL'):
            cap -= 5
        return cltv <= cap

    if rules_lib.same(property_type, '2-4 Unit', '2-4 Units'):
        cltv = ctx['LoanCore.cltv_percent']
        missing = rules_lib.gaps(cltv=cltv)
        if missing:
            return rules_lib.unknown(*missing)
        return cltv <= 80

    if rules_lib.same(property_type, 'Manufactured Home', 'Manufactured'):
        loan_purpose = ctx['LoanCore.loan_purpose']
        cltv = ctx['LoanCore.cltv_percent']
        missing = rules_lib.gaps(loan_purpose=loan_purpose, cltv=cltv)
        if missing:
            return rules_lib.unknown(*missing)
        if rules_lib.same(loan_purpose, 'Purchase'):
            cap = 65
        elif rules_lib.same(loan_purpose, 'Refi R/T'):
            cap = 60
        elif rules_lib.same(loan_purpose, 'Refi C/O'):
            cap = 60
        else:
            return rules_lib.unknown('LoanCore.loan_purpose')
        return cltv <= cap

    return True

