def check(ctx):
    is_rural = ctx['SubjectProperty.is_rural']
    property_type = ctx['SubjectProperty.property_type']
    missing = rules_lib.gaps(is_rural=is_rural, property_type=property_type)
    if missing:
        return rules_lib.unknown(*missing)

    rural = rules_lib.flag(is_rural)
    if rural is None:
        return rules_lib.unknown('SubjectProperty.is_rural')
    is_unique = rules_lib.same(property_type, 'unique')
    if not rural and not is_unique:
        return True

    loan_purpose = ctx['LoanCore.loan_purpose']
    cltv_percent = ctx['LoanCore.cltv_percent']
    representative_score = ctx['CreditReport.representative_score']
    missing = rules_lib.gaps(
        loan_purpose=loan_purpose,
        cltv_percent=cltv_percent,
        representative_score=representative_score,
    )
    if missing:
        return rules_lib.unknown(*missing)

    if rules_lib.same(loan_purpose, 'purchase'):
        cltv_cap = 80
    elif rules_lib.same(loan_purpose, 'refi r/t', 'refinance rate and term'):
        cltv_cap = 75
    elif rules_lib.same(loan_purpose, 'refi c/o', 'refinance cash-out'):
        cltv_cap = 70
    else:
        return rules_lib.unknown('LoanCore.loan_purpose')

    return cltv_percent <= cltv_cap and representative_score >= 700

