def check(ctx):
    score = ctx['CreditReport.representative_score']
    interest_only = ctx['MortgageLoanInformation.is_interest_only']
    escrow_waived = ctx['LoanCore.is_escrow_waived']
    reserves = ctx['RatioSet.reserves_months']

    missing = rules_lib.gaps(
        representative_score=score,
        interest_only=interest_only,
        escrow_waived=escrow_waived,
        reserves_months=reserves,
    )
    if missing:
        return rules_lib.unknown(*missing)

    score_value = rules_lib.ratio(score, 1)
    reserves_value = rules_lib.ratio(reserves, 1)
    interest_only_flag = rules_lib.flag(interest_only)
    escrow_waived_flag = rules_lib.flag(escrow_waived)

    invalid = []
    if score_value is None:
        invalid.append('representative_score')
    if reserves_value is None:
        invalid.append('reserves_months')
    if interest_only_flag is None:
        invalid.append('interest_only')
    if escrow_waived_flag is None:
        invalid.append('escrow_waived')
    if invalid:
        return rules_lib.unknown(*invalid)

    return (
        score_value >= 700
        and not interest_only_flag
        and not escrow_waived_flag
        and reserves_value >= 6
    )

