def check(ctx):
    has_event = ctx['Borrower.has_bankruptcy_or_foreclosure']
    missing = rules_lib.gaps(has_bankruptcy_or_foreclosure=has_event)
    if missing:
        return rules_lib.unknown(*missing)

    event_flag = rules_lib.flag(has_event)
    if event_flag is None:
        return rules_lib.unknown('Borrower.has_bankruptcy_or_foreclosure')
    if not event_flag:
        return True

    months = ctx['Borrower.months_since_bankruptcy_or_foreclosure']
    missing = rules_lib.gaps(months_since_bankruptcy_or_foreclosure=months)
    if missing:
        return rules_lib.unknown(*missing)
    if rules_lib.band(months, [(0, True)], above=True) is None:
        return rules_lib.unknown('Borrower.months_since_bankruptcy_or_foreclosure')

    if months < 12:
        return False
    if months >= 36:
        return True

    if 12 <= months <= 23:
        maximum = 65
    elif 24 <= months <= 35:
        purpose = ctx['LoanCore.loan_purpose']
        missing = rules_lib.gaps(loan_purpose=purpose)
        if missing:
            return rules_lib.unknown(*missing)
        if rules_lib.same(purpose, 'purchase'):
            maximum = 80
        elif rules_lib.same(purpose, 'refi R/T', 'refi C/O'):
            maximum = 75
        else:
            return rules_lib.unknown('LoanCore.loan_purpose')
    else:
        return rules_lib.unknown('Borrower.months_since_bankruptcy_or_foreclosure')

    cltv = ctx['LoanCore.cltv_percent']
    missing = rules_lib.gaps(cltv_percent=cltv)
    if missing:
        return rules_lib.unknown(*missing)
    within_maximum = rules_lib.band(cltv, [(maximum, True)], above=False)
    if within_maximum is None:
        return rules_lib.unknown('LoanCore.cltv_percent')
    return within_maximum

