def check(ctx):
    amount = ctx['LoanCore.total_loan_amount_usd']
    score = ctx['CreditReport.representative_score']
    missing = rules_lib.gaps(amount=amount, score=score)
    if missing:
        return rules_lib.unknown(*missing)

    amount_in_range = rules_lib.band(
        amount, [(1500000, False), (2000000, True)], above=False
    )
    if amount_in_range is None:
        return rules_lib.unknown('amount')
    if not amount_in_range:
        return False

    score_rule = rules_lib.band(score, [(619, False), (639, 'purchase only')], above=True)
    if score_rule is None:
        return rules_lib.unknown('score')
    if score_rule is False:
        return False
    if score_rule == 'purchase only':
        purpose = ctx['LoanCore.loan_purpose']
        missing = rules_lib.gaps(purpose=purpose)
        if missing:
            return rules_lib.unknown(*missing)
        return rules_lib.same(purpose, 'purchase')
    return True

