def check(ctx):
    rating = ctx['CreditReport.housing_history_rating']
    purpose = ctx['LoanCore.loan_purpose']
    cltv = ctx['LoanCore.cltv_percent']

    missing = rules_lib.gaps(rating=rating, purpose=purpose, cltv=cltv)
    if missing:
        return rules_lib.unknown(*missing)

    if rules_lib.same(rating, '0x120x12'):
        return False

    if rules_lib.same(rating, '1x30x12'):
        purchase_max, refi_max = 80, 75
    elif rules_lib.same(rating, '0x60x12'):
        purchase_max, refi_max = 75, 70
    elif rules_lib.same(rating, '0x90x12'):
        purchase_max, refi_max = 65, 65
    else:
        return rules_lib.unknown('CreditReport.housing_history_rating')

    if rules_lib.same(purpose, 'Purchase'):
        maximum = purchase_max
    elif rules_lib.same(purpose, 'Refi R/T', 'Refi C/O'):
        maximum = refi_max
    else:
        return rules_lib.unknown('LoanCore.loan_purpose')

    return cltv <= maximum

