    months = ctx['Borrower.months_since_short_sale_dil_or_modification']
    purpose = ctx['LoanCore.loan_purpose']
    missing = rules_lib.gaps(months_since=months, loan_purpose=purpose)
    if missing:
        return rules_lib.unknown(*missing)

    if rules_lib.same(purpose, 'purchase'):
        purpose_column = 'purchase'
    elif rules_lib.same(purpose, 'Refi R/T') or rules_lib.same(purpose, 'Refi C/O'):
        purpose_column = 'refinance'
    else:
        return rules_lib.unknown('loan_purpose')

    if months >= 24:
        return True
    elif months >= 12:
        maximum = 80 if purpose_column == 'purchase' else 75
    else:
        maximum = 75 if purpose_column == 'purchase' else 70

    cltv = ctx['LoanCore.cltv_percent']
    missing = rules_lib.gaps(cltv=cltv)
    if missing:
        return rules_lib.unknown(*missing)
    return cltv <= maximum

