import re
import rules_lib

def check(ctx):
    penalty = ctx['LoanCore.prepayment_penalty_structure']
    state = ctx['SubjectProperty.state']

    if rules_lib.same(state, 'does not allow prepayment penalties'):
        return True

    years = None
    if rules_lib.known(penalty) and isinstance(penalty, str):
        match = re.search(r'(?<!\d)(\d+(?:\.\d+)?)\s*(?:years?|yrs?)\b', penalty, re.IGNORECASE)
        if match:
            years = float(match.group(1))

    if years is not None and years >= 3:
        return True
    if years is not None and rules_lib.same(state, 'allows prepayment penalties'):
        return False

    missing = rules_lib.gaps(prepayment_penalty_structure=penalty, state=state)
    if missing:
        return rules_lib.unknown(*missing)
    return rules_lib.unknown('state-law exception or prepayment-penalty term')

