def check(ctx):
    channel = ctx['LoanCore.channel']
    obligations = ctx['RatioSet.total_monthly_obligation_usd']
    income = ctx['RatioSet.total_monthly_income_usd']

    missing = rules_lib.gaps(
        channel=channel,
        obligations=obligations,
        income=income,
    )
    if missing:
        return rules_lib.unknown(*missing)

    channel_name = rules_lib.match(channel, ('Wholesale', 'Correspondent'))
    if channel_name is None:
        return rules_lib.unknown('recognized channel')

    dti = rules_lib.ratio(obligations, income)
    if dti is None:
        return rules_lib.unknown('computable DTI')

    channel_minimum_dscr = {
        'Wholesale': 1.0,
        'Correspondent': 1.2,
    }[channel_name]
    dti_meets_stated_cap = dti <= 0.43

    # The DTI cap and channel minimum are stated, but the achieved DSCR is
    # unavailable and Q-14 leaves the DTI alternative unresolved.
    return rules_lib.unknown('achieved DSCR', 'Q-14 DTI alternative')

