def check(ctx):
    score = ctx['CreditReport.representative_score']
    missing = rules_lib.gaps(score=score)
    if missing:
        return rules_lib.unknown(*missing)

    if score < 700:
        return True

    cltv = ctx['LoanCore.cltv_percent']
    purpose = ctx['LoanCore.loan_purpose']
    channel = ctx['LoanCore.channel']
    missing = rules_lib.gaps(cltv=cltv, purpose=purpose, channel=channel)
    if missing:
        return rules_lib.unknown(*missing)

    if score >= 730:
        purchase_max, rate_term_max, cash_out_max = 80, 80, 75
    elif score >= 721:
        purchase_max, rate_term_max, cash_out_max = 80, 80, 65
    else:
        purchase_max, rate_term_max, cash_out_max = 80, 80, 55

    if rules_lib.same(purpose, 'purchase'):
        purpose_max = purchase_max
    elif rules_lib.same(purpose, 'rate & term'):
        purpose_max = rate_term_max
    elif rules_lib.same(purpose, 'cash-out'):
        purpose_max = cash_out_max
    else:
        return rules_lib.unknown('loan_purpose')

    meets_matrix = cltv <= purpose_max
    correspondent_limit_applies = (
        rules_lib.same(channel, 'Correspondent Pricing') and 700 <= score <= 719
    )
    return meets_matrix and (not correspondent_limit_applies or cltv <= 60)

